<?php
include '../includes/auth.php';include '../db.php';include 'purchase_helpers.php';include 'quick_supplier.php';
if(isset($_GET['template'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="supun_purchase_import_template.csv"');$out=fopen('php://output','w');fputcsv($out,['SKU','Quantity','Unit Cost']);fputcsv($out,['REF-240L-001','10','142000.00']);fputcsv($out,['FAN-CEIL-056','25','14500.00']);fclose($out);exit;}
$msg='';$msgType='';$preview=$_SESSION['purchase_import_preview']??[];$quickSupplier=handleQuickSupplier($conn);$newSupplierId=(int)$quickSupplier['id'];if($quickSupplier['handled']){$msg=$quickSupplier['message'];$msgType=$quickSupplier['type'];}
if(isset($_POST['clear_preview'])){unset($_SESSION['purchase_import_preview']);$preview=[];}
if(isset($_POST['preview_import'])){
    $preview=[];$errors=[];
    if(!isset($_FILES['purchase_file'])||$_FILES['purchase_file']['error']!==UPLOAD_ERR_OK){$errors[]='Select a CSV file.';}
    elseif($_FILES['purchase_file']['size']>2*1024*1024){$errors[]='The file must be smaller than 2 MB.';}
    elseif(strtolower(pathinfo($_FILES['purchase_file']['name'],PATHINFO_EXTENSION))!=='csv'){$errors[]='Use the downloadable CSV template. It can be edited with Microsoft Excel.';}
    else{$fh=fopen($_FILES['purchase_file']['tmp_name'],'r');$header=fgetcsv($fh);$expected=['sku','quantity','unit cost'];$normal=array_map(fn($v)=>strtolower(trim((string)$v)),$header?:[]);if($normal!==$expected){$errors[]='Invalid columns. Required: SKU, Quantity, Unit Cost.';}else{$line=1;$lookup=$conn->prepare("SELECT product_id,product_name,sku,stock_qty,unit,cost_price FROM products WHERE sku=? AND status=1 LIMIT 1");while(($row=fgetcsv($fh))!==false){$line++;if(count($row)<3||trim(implode('',$row))==='')continue;$sku=trim($row[0]);$qty=(float)$row[1];$cost=(float)$row[2];$lookup->bind_param('s',$sku);$lookup->execute();$product=$lookup->get_result()->fetch_assoc();$rowErrors=[];if(!$product)$rowErrors[]='Unknown or inactive SKU';if($qty<=0)$rowErrors[]='Quantity must be greater than zero';if($cost<0)$rowErrors[]='Unit cost cannot be negative';$preview[]=['line'=>$line,'sku'=>$sku,'quantity'=>$qty,'unit_cost'=>$cost,'product'=>$product,'errors'=>$rowErrors];} $lookup->close();if(!$preview)$errors[]='The spreadsheet has no product rows.';}fclose($fh);}
    if($errors){$msg=implode(' ',$errors);$msgType='error';unset($_SESSION['purchase_import_preview']);$preview=[];}else{$_SESSION['purchase_import_preview']=$preview;$msg='Spreadsheet read successfully. Review every row before creating the purchase.';$msgType='success';}
}
if(isset($_POST['confirm_import'])){
    $preview=$_SESSION['purchase_import_preview']??[];$supplierId=(int)($_POST['supplier_id']??0);$invoice=trim($_POST['supplier_invoice']??'');$date=$_POST['purchase_date']??date('Y-m-d');$notes=trim($_POST['notes']??'Imported from purchase spreadsheet');$hasErrors=false;foreach($preview as $r)if($r['errors'])$hasErrors=true;
    if(!$preview||$supplierId<=0||$hasErrors){$msg='Select a supplier and correct all spreadsheet errors first.';$msgType='error';}
    else{$conn->begin_transaction();try{$subtotal=0;foreach($preview as $r)$subtotal+=(float)$r['quantity']*(float)$r['unit_cost'];$uid=(int)$_SESSION['user_id'];$s=$conn->prepare("INSERT INTO purchases (supplier_id,supplier_invoice,purchase_date,subtotal,total_amount,notes,created_by) VALUES (?,NULLIF(?,''),?,?,?,?,?)");$s->bind_param('issddsi',$supplierId,$invoice,$date,$subtotal,$subtotal,$notes,$uid);$s->execute();$purchaseId=$conn->insert_id;$s->close();$number=purchaseNumber($purchaseId);$u=$conn->prepare("UPDATE purchases SET purchase_number=? WHERE purchase_id=?");$u->bind_param('si',$number,$purchaseId);$u->execute();$u->close();$item=$conn->prepare("INSERT INTO purchase_items (purchase_id,product_id,quantity,unit_cost,line_total) VALUES (?,?,?,?,?)");foreach($preview as $r){$pid=(int)$r['product']['product_id'];$q=(float)$r['quantity'];$c=(float)$r['unit_cost'];$lt=$q*$c;$item->bind_param('iiddd',$purchaseId,$pid,$q,$c,$lt);$item->execute();}$item->close();$conn->commit();unset($_SESSION['purchase_import_preview']);header('Location:purchase_view.php?id='.$purchaseId.'&imported=1');exit;}catch(Throwable $e){$conn->rollback();$msg=$e->getMessage();$msgType='error';}}
}
$suppliers=$conn->query("SELECT supplier_id,supplier_name FROM suppliers WHERE status=1 ORDER BY supplier_name");$validRows=0;$importTotal=0;$errorRows=0;foreach($preview as $r){if($r['errors'])$errorRows++;else{$validRows++;$importTotal+=(float)$r['quantity']*(float)$r['unit_cost'];}}
?>
