<section class="card table-card-full"><div class="card-head"><h4><i class="fa-solid fa-table-list"></i> Import Preview</h4><form method="post"><button class="btn-small" name="clear_preview"><i class="fa-solid fa-rotate-left"></i> Upload Another</button></form></div><div class="tbl-wrap"><table><thead><tr><th>Line</th><th>SKU</th><th>Matched Product</th><th>Current Stock</th><th>Quantity</th><th>Unit Cost</th><th>Line Total</th><th>Validation</th></tr></thead><tbody><?php foreach($preview as $r):?><tr><td><?php echo (int)$r['line'];?></td><td><strong><?php echo htmlspecialchars($r['sku']);?></strong></td><td><?php echo htmlspecialchars($r['product']['product_name']??'Not found');?></td><td><?php echo isset($r['product'])?number_format((float)$r['product']['stock_qty'],0).' '.htmlspecialchars($r['product']['unit']):'-';?></td><td><?php echo number_format((float)$r['quantity'],3);?></td><td class="money">Rs. <?php echo number_format((float)$r['unit_cost'],2);?></td><td class="money">Rs. <?php echo number_format((float)$r['quantity']*(float)$r['unit_cost'],2);?></td><td><?php if($r['errors']):?><span class="import-error"><?php echo htmlspecialchars(implode(', ',$r['errors']));?></span><?php else:?><span class="import-ok"><i class="fa-solid fa-circle-check"></i> Valid</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card" style="margin-top:18px"><div class="card-head"><h4><i class="fa-solid fa-file-circle-check"></i> Create Draft Purchase</h4></div><form method="post" class="erp-form"><div class="form-grid"><div class="field"><label>Supplier *</label><select class="inp" name="supplier_id" required><option value="">Select supplier</option><?php while($s=$suppliers->fetch_assoc()):?><option value="<?php echo (int)$s['supplier_id'];?>"><?php echo htmlspecialchars($s['supplier_name']);?></option><?php endwhile;?></select></div><div class="field"><label>Purchase Date</label><input class="inp" type="date" name="purchase_date" value="<?php echo date('Y-m-d');?>" required></div><div class="field"><label>Supplier Invoice</label><input class="inp" name="supplier_invoice"></div><div class="field"><label>Internal Note</label><input class="inp" name="notes" value="Imported from purchase spreadsheet"></div></div><p class="muted" style="margin-top:12px">This creates a draft. Open it from the purchase register and click Receive All Stock after checking the physical delivery.</p><button class="btn-primary" name="confirm_import" style="margin-top:12px" <?php echo $errorRows?'disabled title="Correct spreadsheet errors first"':'';?>><i class="fa-solid fa-file-import"></i> Create Draft Purchase</button></form></section><?php endif;?>
